"use client";

import { useState } from "react";

export default function MessageInput({
    conversationId
}) {

    const [message, setMessage] = useState("");

    function handleSubmit(e) {

        e.preventDefault();

        if (!message.trim()) {
            return;
        }

        console.log(
            "Sending:",
            conversationId,
            message
        );

        setMessage("");
    }

    return (
        <form
            onSubmit={handleSubmit}
            style={{
                padding: "15px",
                borderTop: "1px solid #ddd",
                display: "flex",
                gap: "10px"
            }}
        >

            <input
                value={message}
                onChange={(e) =>
                    setMessage(e.target.value)
                }
                placeholder="Type a message..."
                style={{
                    flex: 1,
                    padding: "12px",
                    border: "1px solid #ddd",
                    borderRadius: "8px"
                }}
            />

            <button
                type="submit"
                style={{
                    padding: "12px 20px",
                    cursor: "pointer"
                }}
            >
                Send
            </button>

        </form>
    );
}